<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require_once __DIR__.'/../config/database.php';
if(appConfig('DEMO_MODE','0')!=='1'||appConfig('APP_ENV','development')==='production'){fwrite(STDERR,"เปิด DEMO_MODE=1 และใช้ APP_ENV ที่ไม่ใช่ production ก่อนสร้างข้อมูลสาธิต\n");exit(1);}
$db=(new Database())->getConnection();if(!$db){fwrite(STDERR,"Database unavailable\n");exit(1);}$products=$db->query("SELECT id,name,price FROM products WHERE approval_status='approved' ORDER BY id LIMIT 12")->fetchAll();if(count($products)<3){fwrite(STDERR,"ต้องมีสินค้าอย่างน้อย 3 รายการ\n");exit(1);}
$people=[['demo_mali','มะลิ ใจดี'],['demo_narin','นรินทร์ ครัวบ้าน'],['demo_pim','พิมพ์ชนก รักทำอาหาร'],['demo_ton','ต้นกล้า วันหยุด'],['demo_nok','นกน้อย ชอบอบ'],['demo_beam','บีม เมนูง่าย']];$comments=['ข้อมูลสาธิต: วัสดุดูแข็งแรง ใช้งานง่ายกว่าที่คิดและทำความสะอาดสะดวก','ข้อมูลสาธิต: แพ็กสินค้ามาดี ขนาดตรงตามรายละเอียด เหมาะกับใช้ในครัวทุกวัน','ข้อมูลสาธิต: ทดลองใช้งานแล้วจับถนัดมือ คุณภาพเหมาะสมกับราคา','ข้อมูลสาธิต: สินค้าดูเรียบร้อย ใช้งานได้จริงและจัดเก็บไม่เปลืองพื้นที่','ข้อมูลสาธิต: ชอบรายละเอียดของสินค้าและวิธีใช้งานที่เข้าใจง่าย','ข้อมูลสาธิต: เหมาะสำหรับคนเริ่มทำอาหาร ใช้ไม่ซับซ้อนและดูแลสะดวก'];
try{$db->beginTransaction();foreach($people as $i=>$person){[$username,$name]=$person;$email=$username.'@example.invalid';$stmt=$db->prepare("INSERT INTO users(username,email,password_hash,full_name,phone,address,role,email_verified_at) VALUES(?,?,?,?,'','','customer',NOW()) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name)");$stmt->execute([$username,$email,password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT),$name]);$idStmt=$db->prepare('SELECT id FROM users WHERE username=?');$idStmt->execute([$username]);$userId=(int)$idStmt->fetchColumn();$selected=[];for($j=0;$j<3;$j++)$selected[]=$products[($i*2+$j)%count($products)];$total=array_sum(array_map(fn($p)=>(float)$p['price'],$selected));$orderNo='DEMO-'.strtoupper(substr(hash('sha256',$username),0,12));$order=$db->prepare("INSERT INTO orders(order_no,user_id,subtotal_amount,total_amount,discount_amount,shipping_amount,shipping_name,shipping_phone,shipping_address,payment_method,payment_status,order_status,is_demo,created_at) VALUES(?,?,?,?,0,0,?,'0800000000','ข้อมูลสาธิต จังหวัดสกลนคร 47000','promptpay','paid','completed',1,DATE_SUB(NOW(),INTERVAL ? DAY)) ON DUPLICATE KEY UPDATE total_amount=VALUES(total_amount),is_demo=1");$order->execute([$orderNo,$userId,$total,$total,$name,($i+1)*4]);$orderIdStmt=$db->prepare('SELECT id FROM orders WHERE order_no=?');$orderIdStmt->execute([$orderNo]);$orderId=(int)$orderIdStmt->fetchColumn();$db->prepare('DELETE FROM order_items WHERE order_id=?')->execute([$orderId]);$item=$db->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity,subtotal) VALUES(?,?,?,?,1,?)');$review=$db->prepare("INSERT INTO product_reviews(product_id,user_id,rating,comment,is_demo,created_at) VALUES(?,?,?,?,1,DATE_SUB(NOW(),INTERVAL ? DAY)) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),is_demo=1");foreach($selected as $j=>$product){$item->execute([$orderId,(int)$product['id'],$product['name'],$product['price'],$product['price']]);$review->execute([(int)$product['id'],$userId,4+(($i+$j)%2),$comments[($i+$j)%count($comments)],($i+1)*4]);}}$db->commit();echo 'สร้างข้อมูลสาธิต '.count($people).' ออเดอร์ และ '.(count($people)*3)." รีวิวแล้ว\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
